use crate::{domain::{position::Position,trade::Fill}, economics::CostModel}; use rust_decimal::Decimal; use std::collections::HashMap;
#[derive(Default)] pub struct Portfolio { positions:HashMap<String,Position> }
impl Portfolio { pub fn position(&self,mint:&str)->Option<&Position>{self.positions.get(mint)} pub fn apply_entry(&mut self,mint:String,base_mint:String,token_decimals:u8,base_mint_decimals:u8,position_id:String,fill:&Fill,price:Decimal,signal_id:String,cost_model:CostModel)->Result<(),String>{if fill.output_amount==0{return Err("zero fill".into())}let q=Decimal::from(fill.output_amount);self.positions.entry(mint.clone()).and_modify(|p|{let total=p.quantity+q;p.entry_price_usd=(p.entry_price_usd*p.quantity+price*q)/total;p.quantity=total;p.high_water_price_usd=p.high_water_price_usd.max(price);p.fees_usd+=fill.fees_usd;p.current_value_usd=price*total;p.unrealized_pnl_usd=(price-p.entry_price_usd)*total-p.fees_usd;
if let (Some(input), Some(output), Some(fees)) = (p.entry_input_amount_atomic, p.entry_output_amount_atomic, p.entry_fees_usd) { p.entry_input_amount_atomic=input.checked_add(fill.input_amount); p.entry_output_amount_atomic=output.checked_add(fill.output_amount); p.entry_fees_usd=Some(fees+fill.fees_usd); p.entry_slippage_bps=Some(p.entry_slippage_bps.unwrap_or_default().max(fill.slippage_bps)); } else { p.entry_input_amount_atomic=None; p.entry_output_amount_atomic=None; p.entry_fees_usd=None; p.entry_slippage_bps=None; p.entry_cost_model=None; }}).or_insert(Position{mint:mint.clone(),position_id:Some(position_id),token_mint:Some(mint),base_mint:Some(base_mint),entry_input_amount_atomic:Some(fill.input_amount),entry_output_amount_atomic:Some(fill.output_amount),token_decimals:Some(token_decimals),base_mint_decimals:Some(base_mint_decimals),entry_fees_usd:Some(fill.fees_usd),entry_slippage_bps:Some(fill.slippage_bps),entry_cost_model:Some(cost_model),quantity:q,entry_price_usd:price,entry_time:fill.confirmed_at,entry_signature:fill.signature.clone(),high_water_price_usd:price,realized_pnl_usd:Decimal::ZERO,unrealized_pnl_usd:-fill.fees_usd,fees_usd:fill.fees_usd,current_value_usd:price*q,signal_id,exit_reason:None});Ok(())} }
